import math

def solve_problem():
    solutions = []
    for n in range(2, 31):
        is_solution = True
        # We only need to check k such that 1 <= k < n and gcd(k, n) = 1
        for k in range(1, n):
            if math.gcd(k, n) == 1:
                # Check if k^2 is congruent to 1 modulo n
                if (k * k) % n != 1:
                    is_solution = False
                    break

        if is_solution:
            solutions.append(n)

    print(f"Integers n in the range [2, 30] satisfying the condition: {solutions}")

solve_problem()
